#include <stdio.h>
#include <string.h>

int count_occurrences(const char *str, const char *substr, int overlap) {
    int count = 0;
    size_t str_len = strlen(str);
    size_t substr_len = strlen(substr);

    if (substr_len == 0) return 0; // Edge case: empty substring

    for (size_t i = 0; i <= str_len - substr_len; ++i) {
        if (strncmp(&str[i], substr, substr_len) == 0) {
            count++;
            if (!overlap) i += substr_len - 1;
        }
    }

    return count;
}

int main() {
    printf("%d\n", count_occurrences("the three truths", "th", 0));
    printf("overlap:%d\n", count_occurrences("abababababa", "aba", 1));
    printf("not:    %d\n", count_occurrences("abababababa", "aba", 0));
    return 0;
}

