// Structure to hold factors of an integer
typedef struct {
    int *list;     // Array to store factors
    short count;  // Number of factors stored in the list
} Factors;

// Function to transfer factors from flist to fctrs
void transferFactors(Factors *fctrs, int *flist, int numFactors) {
    int newSize = fctrs->count + numFactors;

    // Reallocate or allocate memory for the new size
    if (newSize > fctrs->count) {
        fctrs->list = realloc(fctrs->list, newSize * sizeof(int));
    } else {
        fctrs->list = malloc(newSize * sizeof(int));
    }

    // Copy factors from flist to fctrs
    for (int i = 0; i < numFactors; i++) {
        fctrs->list[fctrs->count + i] = flist[i];
    }

    fctrs->count = newSize;
}

// Function to find and store factors of a number in the Factors structure
Factors *findFactors(int number, Factors *factors) {
    int factorList[301];  // Temporary array to hold factors
    int index = 0;        // Index for factorList

    // Reset count and free previous list
    factors->count = 0;
    free(factors->list);
    factors->list = NULL;

    // Find factors up to the square root of the number
    for (int divisor = 1; divisor * divisor < number; divisor++) {
        if (number % divisor == 0) {  // If divisor is a factor
            if (index == 300) {       // If factorList is full, transfer to factors
                transferFactors(factors, factorList, index);
                index = 0;
            }
            factorList[index++] = divisor;          // Add divisor
            factorList[index++] = number / divisor;  // Add corresponding factor
        }
    }

    // If the number is a perfect square, add its square root once
    if (number % (int)(number * 0.5) == 0) {
        factorList[index++] = (int)(number * 0.5);
    }

    // Transfer any remaining factors in factorList to factors
    if (index > 0) {
        transferFactors(factors, factorList, index);
    }

    return factors;
}

