// Function to generate a string of 'n' pairs of brackets.
std::string generate(int n, char left = '[', char right = ']') {
    std::string str(n, left);  // Create a string with 'n' left brackets.
    str.append(n, right);      // Append 'n' right brackets to the string.
    std::random_shuffle(str.begin(), str.end()); // Shuffle the characters in the string.
    return str;
