// Function to check if the brackets in the string are balanced.
bool isBalanced(const std::string &str, char left = '[', char right = ']') {
    int balanceCount = 0; // Counter to track the balance of brackets.

    for (char ch : str) { // Iterate through each character in the string.
        if (ch == left)
            balanceCount++; // Increment count for a left bracket.
        else if (ch == right)
            balanceCount--; // Decrement count for a right bracket.

        // If at any point the count is negative, there are more right brackets than left.
        if (balanceCount < 0) return false;
    }

    // The string is balanced if the final count is zero.
    return balanceCount == 0;
}

