// Function to perform binary search iteratively
int iterative_binary_search(int *array, int size, int target) {
    int left = 0;
    int right = size - 1;

    while (left <= right) {
        // Calculate the middle index
        int mid = left + ((right - left) / 2);

        // Check if the target is at the middle
        if (array[mid] == target) {
            return mid; // Target found, return its index
        }
        // If target is greater, ignore the left half
        else if (array[mid] < target) {
            left = mid + 1;
        }
        // If target is smaller, ignore the right half
        else {
            right = mid - 1;
        }
    }

    return -1; // Target not found
}

// Function to perform binary search recursively
int recursive_binary_search(int *array, int target, int left, int right) {
    // Base case: if the range is invalid
    if (right < left) {
        return -1; // Target not found
    }

    // Calculate the middle index
    int mid = left + ((right - left) / 2);

    // Check if the target is at the middle
    if (array[mid] == target) {
        return mid; // Target found, return its index
    }
    // If target is greater, search in the right half
    else if (array[mid] < target) {
        return recursive_binary_search(array, target, mid + 1, right);
    }
    // If target is smaller, search in the left half
    else {
        return recursive_binary_search(array, target, left, mid - 1);
    }
}

