    size_t len = mbstowcs(NULL, s, 0) + 1; // Calculate the length of the wide character array
    if (!len) return NULL;

    wchar_t *u = malloc(sizeof(wchar_t) * len); // Allocate memory for the wide characters
    mbstowcs(u, s, len); // Convert multi-byte string to wide characters
    return u;
}

// Function to reverse a wide character string
wchar_t* ws_reverse(const wchar_t* u) {
    size_t length = wcslen(u); // Get the length of the input string
    wchar_t *out = malloc(sizeof(wchar_t) * (length + 1)); // Allocate memory for the reversed string
    out[length] = L'\0'; // Null-terminate the output string

    int j = 0;
    while (length > 0) {
        // Find the last non-combining character
        int i = length - 1;
        while (i > 0 && is_combining_mark(u[i])) {
            i--;
        }
        wcsncpy(out + j, u + i, length - i); // Copy the substring to the output string
        j += length - i;
        length = i; // Update the length for the next iteration
    }
    return out;
}

