        Stack<int> stack = new Stack<int>(); // Stack to help with generating combinations.
        stack.Push(0); // Start with index 0.

        while (stack.Count > 0) // Continue until there are no more indices to process.
        {
            int index = stack.Count - 1; // Get the current index from the stack.
            int value = stack.Pop(); // Pop the current value.

            while (value < n) // Iterate through possible values for the current index.
            {
                result[index++] = ++value; // Increment value and store it in the result array.
                stack.Push(value); // Push the new value onto the stack.

                if (index == m) // If we have filled 'm' indices, yield the result.
                {
                    yield return result;
                    break;
                }
            }
        }
    }

