import java.util.HashMap;
import java.util.Map;

public class ShannonEntropyCalculator {

    // Method to calculate the Shannon entropy of a given string.
    public static double calculateShannonEntropy(String input) {
        int totalCharacters = 0;
        Map<Character, Integer> characterCounts = new HashMap<>();

        // Count occurrences of each character in the string.
        for (int i = 0; i < input.length(); ++i) {
            char currentChar = input.charAt(i);
            if (characterCounts.containsKey(currentChar)) {
                characterCounts.put(currentChar, characterCounts.get(currentChar) + 1);
            } else {
                characterCounts.put(currentChar, 1);
            }
            totalCharacters++;
        }

        double entropy = 0.0;
        // Calculate the entropy using the formula: -sum(p * log2(p))
        for (Map.Entry<Character, Integer> entry : characterCounts.entrySet()) {
            double probability = (double) entry.getValue() / totalCharacters;
            entropy += probability * log2(probability);
        }
        return -entropy;
    }

    // Helper method to calculate the base-2 logarithm.
    private static double log2(double value) {
        return Math.log(value) / Math.log(2);
    }

    public static void main(String[] args) {
        String[] testStrings = {
            "1223334444",
            "1223334444555555555", 
            "122333", 
            "1227774444",
            "aaBBcccDDDD",
            "1234567890abcdefghijklmnopqrstuvwxyz",
            "Rosetta Code",
        };

        // Calculate and print the entropy for each test string.
        for (String test : testStrings) {
            double entropy = calculateShannonEntropy(test);
            System.out.printf("Shannon entropy of %40s: %.12f%n", "\"" + test + "\"", entropy);
        }
    }
}

