object Caesar {
    fun encrypt(s: String, key: Int): String {
        val offset = key % 26
        if (offset == 0) return s

        return s.map { c ->
            when {
                c in 'A'..'Z' -> ((c - 'A' + offset) % 26 + 'A'.toInt()).toChar()
                c in 'a'..'z' -> ((c - 'a' + offset) % 26 + 'a'.toInt()).toChar()
                else -> c
            }
        }.joinToString("")
    }

    fun decrypt(s: String, key: Int): String {
        return encrypt(s, 26 - key)
    }
