// Function to perform binary search on a sorted array
func binarySearch<T: Comparable>(array: [T], target: T) -> Int? {
    // Helper function to perform the recursive search
    func search(low: Int, high: Int) -> Int? {
        // Base case: if low is greater than high, the target is not in the array
        guard low <= high else { return nil }

        // Calculate the middle index
        let mid = (low + high) / 2

        // Compare the middle element with the target
        if array[mid] > target {
            // If the middle element is greater than the target, search in the left half
            return search(low: low, high: mid - 1)
        } else if array[mid] < target {
            // If the middle element is less than the target, search in the right half
            return search(low: mid + 1, high: high)
        } else {
            // If the middle element is equal to the target, return the index
            return mid
        }
    }

    // Start the search from the entire range of the array
    return search(low: 0, high: array.count - 1)
}

